const toolbar='<div class="theme-demo-bar"><span class="theme-demo-copy">Demonstration school · Illustrative prices and learner stories</span><div class="device-tools" role="group" aria-label="Preview screen size"><button type="button" data-device="desktop" aria-pressed="true" title="Desktop view" aria-label="Desktop view">'+icons.desktop+'</button><button type="button" data-device="tablet" aria-pressed="false" title="iPad view" aria-label="iPad view">'+icons.tablet+'</button><button type="button" data-device="phone" aria-pressed="false" title="Mobile view" aria-label="Mobile view">'+icons.phone+'</button></div><div class="theme-tools"><label for="theme-picker">Try your colours</label><select id="theme-picker" aria-label="Website colour theme"><option value="green">Green</option><option value="blue">Blue</option><option value="purple">Purple</option><option value="charcoal">Charcoal</option><option value="emerald">Emerald</option><option value="red">Red</option><option value="orange">Orange</option><option value="amber">Amber / gold</option><option value="pink">Pink</option><option value="burgundy">Burgundy</option><option value="navy">Navy</option></select></div></div>';
const wrapper='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Greenlight Driving · Yotion live example</title><style>*{box-sizing:border-box}body{margin:0;background:#edf2ed;color:#172e2b;font:14px/1.5 Arial,sans-serif}.yotion-example-cta{display:flex;justify-content:center;align-items:center;gap:15px;flex-wrap:wrap;background:#172e2b;color:#fff;padding:11px 18px}.yotion-example-cta strong{color:#cfe77a}.yotion-example-cta a{color:#172e2b;background:#cfe77a;text-decoration:none;border-radius:22px;padding:8px 14px;font-weight:700}.theme-demo-bar{display:flex;align-items:center;justify-content:center;gap:clamp(12px,2vw,30px);flex-wrap:wrap;background:#fff;padding:13px 20px;border-bottom:1px solid #dbe5da}.theme-demo-copy{font-size:13px;color:#516a5c}.theme-tools,.device-tools{display:flex;align-items:center;gap:7px}.theme-tools label{font-weight:700;white-space:nowrap}.theme-tools select{padding:9px;border:1px solid #cbd9c9;border-radius:8px;background:#fff;color:#172e2b}.device-tools{background:#eff4ed;padding:4px;border-radius:10px}.device-tools button{display:inline-flex;align-items:center;justify-content:center;width:40px;height:36px;border:0;border-radius:7px;background:transparent;color:#4b6759;cursor:pointer}.device-tools button[aria-pressed=true]{background:#175e4c;color:white;box-shadow:0 2px 8px #173b2126}.device-tools button:hover:not([aria-pressed=true]){background:#dce9d9}.device-tools button:focus-visible,.theme-tools select:focus-visible{outline:3px solid #79a45e;outline-offset:2px}.viewport{display:flex;justify-content:center;padding:20px 10px 40px;overflow-x:auto}.frame{width:100%;max-width:100%;height:calc(100dvh - 160px);min-height:540px;background:#fff;border:0;box-shadow:0 14px 44px #1b39271c;transition:width .35s ease,max-width .35s ease,border-radius .35s}.frame.tablet{width:768px;max-width:100%;border:8px solid #263d37;border-radius:17px}.frame.phone{width:390px;max-width:100%;border:7px solid #263d37;border-radius:20px}iframe{display:block;width:100%;height:100%;border:0;background:#fff}@media(max-width:600px){.theme-demo-bar{gap:9px;padding:12px}.theme-demo-copy{width:100%;text-align:center}.viewport{padding:10px 4px}.frame{min-height:600px}}@media(prefers-reduced-motion:reduce){.frame{transition:none}}</style></head><body><aside class="yotion-example-cta"><span><strong>Example website ·</strong> See how Yotion could personalise this for your driving school.</span><a href="/">Back to Yotion</a></aside>'+toolbar+'<main class="viewport"><div id="frame" class="frame"><iframe id="sample-frame" src="/sample?embedded=1" title="Greenlight Driving interactive website demonstration"></iframe></div></main><script>(function(){var frame=document.getElementById("frame"),view=document.getElementById("sample-frame"),picker=document.getElementById("theme-picker");function sendTheme(){try{var inner=view.contentWindow.document.getElementById("theme-picker");if(inner){inner.value=picker.value;inner.dispatchEvent(new Event("change",{bubbles:true}));}}catch(e){}}document.querySelectorAll("[data-device]").forEach(function(button){button.addEventListener("click",function(){frame.className="frame "+(button.dataset.device==="desktop"?"":button.dataset.device);document.querySelectorAll("[data-device]").forEach(function(b){b.setAttribute("aria-pressed",String(b===button));});});});picker.addEventListener("change",sendTheme);view.addEventListener("load",function(){try{var inner=view.contentWindow.document.getElementById("theme-picker");if(inner){picker.value=inner.value;}}catch(e){}});})();</script></body></html>';
export function GET(request:NextRequest) {
 const embedded=new URL(request.url).searchParams.get("embedded")==="1";
 const page=embedded?html.slice(0,html.indexOf("<aside class="))+html.slice(html.indexOf("<header>")):wrapper;
 return new Response(page,{headers:{"Content-Type":"text/html; charset=utf-8","X-Content-Type-Options":"nosniff","X-Robots-Tag":"noindex, nofollow","Cache-Control":"no-store"}});
}
